"use strict";
const test=require("node:test"),assert=require("node:assert/strict");
const {fixture,commit,projection,bridge,gate}=require("./oath-committed-fixture.cjs");
const {editTaskContent}=require("../domain/tasks");
const focus=(name,fn)=>test(name,{timeout:5000},fn);
const until=async predicate=>{for(let i=0;i<20000;i++){if(predicate())return;await Promise.resolve();}throw Error("Deferred operation did not reach expected boundary");};
function edit(f,completed){const task=f.oath.work[0].task,result=editTaskContent(f.contents.get(task.path),{...task,completed},line=>line.replace(/\[[ xX]\]/,completed?"[x]":"[ ]"));f.contents.set(task.path,result.content);f.oath.changed(result.edit);return result;}
for(const sequence of["complete-reopen","latch-failure-reopen","steps-only","time","missing-end","duplicate-notifications"])
focus("original/current durable fulfillment and outcome parity: "+sequence,async()=>{const results=[];for(const original of[true,false]){const f=fixture({original});try{commit(f);f.oath.error=()=>{};await f.oath.refresh();let pending=null;
 if(sequence==="complete-reopen"||sequence==="latch-failure-reopen"){f.failPersist(sequence==="latch-failure-reopen");edit(f,true);await f.oath.refresh();pending=structuredClone(f.oath.pendingFulfilment??null);if(sequence==="latch-failure-reopen")assert(pending);edit(f,false);f.failPersist(false);await f.oath.refresh();assert(f.oath.fulfilled);}
 if(sequence==="steps-only"){const p=f.oath.work[0].task.path;f.contents.set(p,f.contents.get(p).replace("- [ ] Nested","- [x] Nested"));await f.oath.refresh();assert.equal(f.oath.fulfilled,false);}
 if(sequence==="time"){f.oath.now=()=>f.now+1500000;await f.oath.refresh(false);assert(f.oath.fulfilled);}
 if(sequence==="missing-end"){f.remove(f.files.get(f.oath.work[0].task.path));await f.oath.refresh();assert.equal(f.oath.fulfilled,false);}
 if(sequence==="duplicate-notifications"){edit(f,true);await Promise.all([f.oath.refresh(),f.oath.refresh(),f.oath.refresh()]);assert(f.oath.fulfilled);}
 const result=await f.oath.end(f.oath.current.id,"broken");assert.equal(result,"ended");await f.oath.end("committed-oath","broken");assert.equal(f.oath.bucket.history.length,1);results.push({current:f.oath.current,history:f.oath.bucket.history,saved:f.saved,pending,snapshot:f.snapshot(),persists:f.counts.persists});}finally{await f.close();}}assert.deepEqual(results[1],results[0]);});
focus("out-of-order direct reads cannot overwrite newer title/source",async()=>{const f=fixture();try{commit(f);await f.oath.resolveWork();const reads=[],read=f.adapter.resolveOathWork.bind(f.adapter);f.adapter.resolveOathWork=async r=>{const result=await read(r),g=gate();reads.push({result,g});return g.promise;};const a=f.oath.resolveWork();await until(()=>reads.length===1);const p="Projects/Private/Tasks.md";f.contents.set(p,f.contents.get(p).replace("Parent **markdown**","New current title"));const b=f.oath.resolveWork();await until(()=>reads.length===2);reads[1].g.resolve(reads[1].result);await b;assert.equal(f.oath.work[0].task.text,"New current title");reads[0].g.resolve(reads[0].result);await a;assert.equal(f.oath.work[0].task.text,"New current title");}finally{await f.close();}});
focus("completion while an older read is pending retains local feedback and latch",async()=>{const f=fixture();try{commit(f);await f.oath.refresh();const reads=[],read=f.adapter.resolveOathWork.bind(f.adapter);f.adapter.resolveOathWork=async r=>{const result=await read(r),g=gate();reads.push({result,g});return g.promise;};const old=f.oath.refresh();await until(()=>reads.length===1);edit(f,true);assert(f.oath.work[0].task.completed);assert(f.oath.pendingFulfilment);reads[0].g.resolve(reads[0].result);await until(()=>reads.length===2);assert(f.oath.work[0].task.completed);reads[1].g.resolve(reads[1].result);await old;assert(f.oath.current.fulfilledAt!=null);assert(f.oath.work[0].task.completed);assert.equal(f.counts.persists,1);}finally{await f.close();}});
focus("source mutation during fresh read coalesces multiple invalidations without stale publication",async()=>{const f=fixture();try{commit(f);await f.oath.refresh();const read=f.vault.read,first=gate();let blocked=false;f.vault.read=async file=>{const value=await read(file);if(!blocked){blocked=true;await first.promise;}return value;};const old=f.oath.refresh();await until(()=>blocked);const path="Projects/Private/Tasks.md";f.contents.set(path,f.contents.get(path).replace("Parent **markdown**","After source invalidation"));f.index(f.files.get(path));const before=f.counts.queries;const b=f.oath.refresh(),c=f.oath.refresh();assert.equal(b,c);first.resolve();await old;assert.equal(f.oath.work[0].task.text,"After source invalidation");assert.equal(f.counts.queries-before,1);}finally{await f.close();}});
focus("source rename during validation cannot publish an old locator",async()=>{const f=fixture();try{commit(f);await f.oath.refresh();const read=f.vault.read,g=gate();let blocked=false;f.vault.read=async file=>{const value=await read(file);if(!blocked){blocked=true;await g.promise;}return value;};const old=f.oath.refresh();await until(()=>blocked);f.move(f.files.get("Projects/Private/Tasks.md"),"Projects/Private/Renamed-During-Read.md");void f.oath.refresh();g.resolve();await old;assert.equal(f.oath.work[0].task.path,"Projects/Private/Renamed-During-Read.md");}finally{await f.close();}});
focus("disposal prevents late read publication and preserves shared facade",async()=>{const f=fixture();try{commit(f);await f.oath.resolveWork();const work=f.oath.work,read=f.adapter.resolveOathWork.bind(f.adapter),g=gate();let waiting=false;f.adapter.resolveOathWork=async r=>{const q=await read(r);waiting=true;await g.promise;return q;};const pending=f.oath.resolveWork();await until(()=>waiting);f.oath.destroy();g.resolve();await pending;assert.equal(f.oath.work,work);assert.equal(f.plugin.taskData.subscribers.size,0);assert(await f.service.queryHistory({projection:"recorded"}));}finally{await f.close();}});
focus("accepted enrollment persistence/hydration survives read disposal",async()=>{const f=fixture();try{const g=gate(),save=f.plugin.dataStore.save;let waiting=false;f.plugin.dataStore.save=async data=>{waiting=true;await g.promise;return save(data);};const accepted=bridge(f,{preexisting:true});await until(()=>waiting);f.oath.destroy();g.resolve();await accepted;assert.equal(f.oath.current.tasks[0].id,"source-existing");assert(f.oath.work[0].task);assert.equal(f.oath.awaitingIndex.size,1);assert.equal(f.counts.persists,1);}finally{await f.close();}});
focus("candidate and committed readers share one backend and retain independent cleanup",async()=>{const f=fixture();try{commit(f);await f.oath.start();const cleanup=[],component={register:fn=>cleanup.push(fn)},reader=require("../services/oath-candidate-read").createOathCandidateRead(f.oath,component);await reader.selectWorkspace({type:"project",id:"private"});assert.equal(f.plugin.taskData.subscribers.size,1);f.oath.destroy();assert.equal(f.plugin.taskData.subscribers.size,1);await reader.retry();assert.equal(reader.state.status,"ready");cleanup.forEach(fn=>fn());assert.equal(f.plugin.taskData.subscribers.size,0);}finally{await f.close();}});
focus("countdown ticks use zero task/source reads and repeated start owns one watcher",async()=>{const f=fixture();try{commit(f);await f.oath.start();const timer=f.oath.timer;await f.oath.start();assert.equal(f.oath.timer,timer);assert.equal(f.plugin.taskData.subscribers.size,1);const counts={...f.counts};for(let i=0;i<100;i++){f.oath.tickDisplay();await f.oath.refresh(false);}assert.deepEqual(f.counts,counts);}finally{await f.close();}});
focus("index unavailability retains work; later readiness hydrates normally",async()=>{const f=fixture();try{commit(f);await f.oath.start();const work=f.oath.work;f.dv.index.initialized=false;await f.oath.refresh();assert.equal(f.oath.work,work);f.dv.index.initialized=true;await f.oath.refresh();assert(f.oath.work[0].task);}finally{await f.close();}});
focus("scheduled activation and cross-device histories match original",async()=>{const results=[];for(const original of[true,false]){const f=fixture({original});try{commit(f,["parent"],{type:"project",id:"private"},"scheduled");f.wizard.data.oathsByDevice.other={current:{id:"other"},history:[{id:"other-history",state:"broken"}]};await f.oath.start();assert.equal(f.oath.current.state,"scheduled");f.oath.now=()=>f.now+70000;await f.oath.refresh(false);assert(f.oath.active);await f.oath.end(f.oath.current.id,"broken");results.push({saved:f.saved,other:f.wizard.data.oathsByDevice.other,current:f.oath.current});}finally{await f.close();}}assert.deepEqual(results[1],results[0]);});
focus("legacy scheduled Oath without a workspace reaches original invalidation",async()=>{const f=fixture();try{commit(f,[],null,"scheduled");delete f.wizard.data.oathsByDevice[f.plugin.dataStore.deviceId].current.workspace;f.oath.now=()=>f.now+70000;await f.oath.refresh();assert.equal(f.oath.current.state,"invalid");}finally{await f.close();}});
focus("query failure after destruction is ignored without obsolete feedback",async()=>{const f=fixture();try{commit(f);const g=gate();let waiting=false;f.adapter.resolveOathWork=async()=>{waiting=true;await g.promise;throw Error("Late closed query");};const pending=f.oath.resolveWork();await until(()=>waiting);f.oath.destroy();g.resolve();assert.equal(await pending,false);}finally{await f.close();}});
focus("workspace root changed while pending cannot publish obsolete ownership",async()=>{const f=fixture();try{commit(f);await f.oath.resolveWork();const work=f.oath.work,read=f.adapter.resolveOathWork.bind(f.adapter),g=gate();let waiting=false;f.adapter.resolveOathWork=async r=>{const q=await read(r);waiting=true;await g.promise;return q;};const pending=f.oath.resolveWork();await until(()=>waiting);f.owners[0].root="Projects/Changed";g.resolve();await pending;assert.equal(f.oath.work,work);assert.equal(f.oath.needsRead,true);f.adapter.resolveOathWork=read;await f.oath.refresh();assert.equal(f.oath.work[0].task,null);}finally{await f.close();}});
focus("two independent window/device hosts dispose without crossing ownership",async()=>{const a=fixture(),b=fixture();try{commit(a);commit(b);b.plugin.dataStore.deviceId="different-window-device";b.oath.deviceId="different-window-device";commit(b);await Promise.all([a.oath.start(),b.oath.start()]);assert.equal(a.plugin.taskData.subscribers.size,1);assert.equal(b.plugin.taskData.subscribers.size,1);a.oath.destroy();await b.oath.refresh();assert(b.oath.work[0].task);assert.equal(b.plugin.taskData.subscribers.size,1);}finally{await a.close();await b.close();}});
focus("accepted end persists once while an older read remains pending",async()=>{const f=fixture();try{commit(f);await f.oath.resolveWork();const read=f.adapter.resolveOathWork.bind(f.adapter),g=gate();let waiting=false;f.adapter.resolveOathWork=async r=>{const q=await read(r);if(!waiting){waiting=true;await g.promise;}return q;};const old=f.oath.resolveWork();await until(()=>waiting);assert.equal(await f.oath.end("committed-oath","broken"),"ended");g.resolve();await old;assert.equal(f.oath.work.length,0);assert.equal(f.oath.bucket.history.length,1);assert.equal(f.oath.current.state,"broken");}finally{await f.close();}});
